type User = { id: number; name: string; email: string; role: 'admin' | 'staff'; active: boolean };
type Lead = { id:number; name:string; category:string; city:string; address:string; phone:string|null; website:string|null; rating:number|null; review_count:number|null; socials:string[]; email:string|null; card_url:string|null; source:string; collected_at:string; website_status:string; audit:Record<string,any>; score:number; score_reasons:{rule:string;points:number}[]; status:string; owner_id:number|null; notes:string; order_value:number; next_contact:string|null; consent:string; version:number; export_allowed:boolean };
type SearchJob = { id:number; criteria:Record<string,any>; status:string; progress:number; found:number; errors:string[]; created_at:string; finished_at?:string };
const statuses = ['Новый','Не связывались','Не дозвонились','Связались','Отказался','Заинтересован','Отправлена демонстрация','Отправлено коммерческое предложение','Ведутся переговоры','Ожидается оплата','Оплатил','В разработке','Заказ завершён','Не связываться повторно'];
