const websiteLabels:Record<string,string> = {not_listed:'Сайт не указан',working:'Сайт работает',unavailable:'Недоступен',check_error:'Ошибка проверки',unchecked:'Не проверен'};
const sourceLabels:Record<string,string> = {yandex:'Яндекс Карты',dgis:'2ГИС','2gis':'2ГИС',manual:'Импорт',demo:'Демонстрация'};
const ruleLabels:Record<string,string> = {not_listed:'Сайт не указан',unavailable:'Сайт недоступен',mobile:'Проблемы мобильной версии',rating:'Высокий рейтинг',reviews:'Более 30 отзывов',priority:'Приоритетная категория',quality:'Качественный сайт'};
const jobsLabels:Record<string,string> = {queued:'В очереди',running:'Выполняется',completed:'Завершён',cancelled:'Остановлен',failed:'Ошибка'};
const pages = [{id:'dashboard',label:'Дашборд',icon:LayoutDashboard},{id:'search',label:'Новый поиск',icon:Search},{id:'leads',label:'База клиентов',icon:Building2},{id:'promising',label:'Перспективные',icon:ListFilter},{id:'crm',label:'CRM',icon:Columns3},{id:'team',label:'Сотрудники',icon:Users},{id:'analytics',label:'Аналитика',icon:ChartNoAxesCombined},{id:'history',label:'История поисков',icon:History},{id:'settings',label:'Настройки',icon:Settings2}];
const money = (n:number=0) => new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(n);
const localInputDate = (value:string|null|undefined) => {if(!value)return '';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const date = (value:string|null|undefined) => value ? new Date(value).toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'}) : 'Не указано';
const list = (value:string) => value.split(/[,;\n]/).map(x=>x.trim()).filter(Boolean);
const err = (error:unknown) => error instanceof Error ? error.message : 'Не удалось выполнить действие';
const safeUrl = (value:string|null|undefined) => { if(!value) return undefined; try { const u=new URL(value); return ['http:','https:'].includes(u.protocol)?u.href:undefined; } catch { return undefined; } };
const pagesDemo = location.hostname.endsWith('github.io');
const demoPasswordHash = 'e590d43952c652da4ed882cd82a5232b8f2d3be99fee93395b7e51412e4e8251';
const demoLead = (id:number,name:string,score:number,rule:string):Lead => ({id,name,category:'Автосервисы',city:'Демонстрационный город',address:'',phone:null,website:null,rating:null,review_count:null,socials:[],email:null,card_url:null,source:'demo',collected_at:new Date().toISOString(),website_status:'not_listed',audit:{},score,score_reasons:[{rule,points:score}],status:'Новый',owner_id:null,notes:'',order_value:0,next_contact:null,consent:'unknown',version:1,export_allowed:false});
function Field({label,children,hint}:{label:string;children:ReactNode;hint?:string}) { return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>; }
function Empty({title,text,action}:{title:string;text:string;action?:ReactNode}) { return <div className="empty"><Building2 size={30} strokeWidth={1.5}/><h3>{title}</h3><p>{text}</p>{action}</div>; }
function Loading(){return <div className="loading" role="status" aria-label="Загрузка"><div/><div/><div/></div>;}
function ErrorBox({message}:{message:string}) {return message?<div className="error" role="alert"><AlertCircle size={18}/><span>{message}</span></div>:null;}
function Score({value}:{value:number}) {const level=value>=80?'высокий':value>=60?'хороший':value>=40?'средний':'низкий';return <span className={`score ${value>=80?'green':value>=60?'yellow':value>=40?'orange':'gray'}`} aria-label={`Оценка ${value} из 100, ${level} приоритет`}>{value}<span aria-hidden="true">/100</span></span>;}
function Toggle({label,checked,onChange,disabled=false}:{label:string;checked:boolean;onChange:(checked:boolean)=>void;disabled?:boolean}) {return <label className="check"><input type="checkbox" checked={checked} disabled={disabled} onChange={e=>onChange(e.target.checked)}/><span>{label}</span></label>;}

export default function App(){
 const [user,setUser]=useState<User|null>(null),[ready,setReady]=useState(false),[setup,setSetup]=useState(false),[bootError,setBootError]=useState('');
 const [page,setPage]=useState(()=>location.hash.slice(1)||'dashboard'),[menu,setMenu]=useState(false),[theme,setTheme]=useState(()=>localStorage.getItem('dus-theme')||'dark');
 const [demo,setDemo]=useState(false);
 const [notice,setNotice]=useState(''),[selected,setSelected]=useState<Lead|null>(null),[revision,setRevision]=useState(0),[users,setUsers]=useState<User[]>([]);
 const refresh=()=>setRevision(v=>v+1);
 const notify=(message:string)=>{setNotice(message);};
 useEffect(()=>{api('/health').then(d=>setDemo(Boolean(d.demo_mode))).catch(()=>{if(pagesDemo)setDemo(true);});},[]);
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('dus-theme',theme);},[theme]);
 useEffect(()=>{if(!notice)return;const timer=setTimeout(()=>setNotice(''),6000);return()=>clearTimeout(timer);},[notice]);
 useEffect(()=>{const change=()=>setPage(location.hash.slice(1)||'dashboard');window.addEventListener('hashchange',change);return()=>window.removeEventListener('hashchange',change);},[]);
 useEffect(()=>{api('/auth/status').then(s=>{setSetup(s.needs_setup);if(!s.needs_setup)return api<User>('/auth/me').then(setUser).catch(e=>{if(e.status!==401)throw e;});}).catch(e=>{if(!pagesDemo)setBootError(err(e));}).finally(()=>setReady(true));},[]);
 useEffect(()=>{if(user)api<User[]>('/users').then(data=>setUsers(Array.isArray(data)?data:(data as any).items||[])).catch(()=>setUsers([user]));},[user,revision]);
 const go=(id:string)=>{location.hash=id;setPage(id);setMenu(false);};
 if(!ready)return <main className="auth-shell"><Loading/></main>;
 if(!user)return <Auth setup={setup} demo={pagesDemo} error={bootError} onLogin={u=>{setUser(u);setSetup(false);}}/>;
 const title=pages.find(p=>p.id===page)?.label||'Дашборд';
 return <div className="app-shell"><a className="skip" href="#main" onClick={e=>{e.preventDefault();const target=document.getElementById('main');target?.focus();target?.scrollIntoView();}}>К содержимому</a>{menu&&<button className="scrim" aria-label="Закрыть меню" onClick={()=>setMenu(false)}/>}
 <aside className={`sidebar ${menu?'open':''}`}><div className="brand"><span className="brand-mark">D</span><strong>DUS <span>Leads</span></strong><Button variant="ghost" size="icon" className="mobile-only" aria-label="Закрыть меню" onClick={()=>setMenu(false)}><X size={19}/></Button></div><div className="nav-spacer" aria-hidden="true"/><nav aria-label="Основная навигация">{pages.map(p=><button key={p.id} className={`nav-item ${page===p.id?'active':''}`} onClick={()=>go(p.id)} aria-current={page===p.id?'page':undefined}><p.icon size={19}/>{p.label}{p.id==='search'&&<Plus size={15} className="nav-end"/>}</button>)}</nav><div className="sidebar-bottom"><p>Данные организаций и работа команды в одном месте.</p><div className="profile"><span className="avatar">{user.name.slice(0,1)}</span><div><strong>{user.name}</strong><small>{user.role==='admin'?'Администратор':'Сотрудник'}</small></div><Button variant="ghost" size="icon" aria-label="Выйти" onClick={async()=>{try{await api('/auth/logout',{method:'POST'});setUser(null);}catch(e){notify(err(e));}}}><LogOut size={17}/></Button></div></div></aside>
 <div className="main-shell"><header className="topbar"><div className="breadcrumbs"><Button variant="ghost" size="icon" className="mobile-only" aria-label="Открыть меню" onClick={()=>setMenu(true)}><Menu size={20}/></Button><span>DUS Leads</span><span className="slash">/</span><strong>{title}</strong></div><div className="top-actions"><span className="workspace-status">Общая база команды</span><Button variant="ghost" size="icon" onClick={()=>setTheme(theme==='dark'?'light':'dark')} aria-label={theme==='dark'?'Включить светлую тему':'Включить тёмную тему'}>{theme==='dark'?<Sun size={18}/>:<Moon size={18}/>}</Button></div></header>
 {demo&&<div className="demo-banner" role="status">Демонстрационный режим. Организации и результаты в этой базе являются учебными данными.</div>}<main id="main" className="content" tabIndex={-1}><div className="page-heading"><div><h1>{title}</h1><p>{({dashboard:'Результаты поиска и работа с клиентами.',search:'Найдите компании по городам, категориям и состоянию сайта.',leads:'Контакты, оценка и история работы с каждой организацией.',promising:'Организации с оценкой от 60 баллов.',crm:'Следующий контакт и движение заказов.',team:'Доступ к общей базе и распределение клиентов.',analytics:'Результаты по городам, категориям и сотрудникам.',history:'Прогресс, результаты и ошибки задач.',settings:'Оценка клиентов, лимиты и подключение источников.'} as Record<string,string>)[page]}</p></div>{['dashboard','leads','promising'].includes(page)&&<Button onClick={()=>go('search')}><Plus size={17}/>Новый поиск</Button>}</div>
 {page==='dashboard'||page==='analytics'?<Dashboard revision={revision} analytics={page==='analytics'} demo={pagesDemo} onOpenSearch={()=>go('search')} onOpenLeads={()=>go('promising')} onSelect={setSelected}/>:page==='search'?<SearchPage notify={notify} onCreated={()=>{refresh();go('history');}}/>:page==='leads'||page==='promising'?<LeadsPage key={page} promising={page==='promising'} users={users} revision={revision} refresh={refresh} notify={notify} onSelect={setSelected}/>:page==='crm'?<CrmPage revision={revision} onSelect={setSelected}/>:page==='team'?<TeamPage user={user} users={users} refresh={refresh} notify={notify}/>:page==='history'?<HistoryPage onSelect={setSelected} notify={notify}/>:page==='settings'?<SettingsPage user={user} notify={notify}/>:<Empty title="Страница не найдена" text="Выберите раздел в боковом меню." action={<Button onClick={()=>go('dashboard')}>Открыть дашборд</Button>}/>} 
 </main><footer className="footer">DUS Leads<span>Оценка клиентов является эвристикой, а не вероятностью покупки.</span></footer></div>
 {selected&&<LeadDetail lead={selected} users={users} onClose={()=>setSelected(null)} onSaved={()=>{refresh();}} notify={notify}/>}{notice&&<div className="toast" role="status"><Check size={17}/><span>{notice}</span><button aria-label="Закрыть уведомление" onClick={()=>setNotice('')}><X size={16}/></button></div>}</div>;
}

function Auth({setup,error,demo=false,onLogin}:{setup:boolean;error:string;demo?:boolean;onLogin:(user:User)=>void}){
 const [busy,setBusy]=useState(false),[message,setMessage]=useState(error);
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setMessage('');const data=Object.fromEntries(new FormData(e.currentTarget));try{if(demo){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(data.password||'')));const hash=Array.from(new Uint8Array(bytes)).map(byte=>byte.toString(16).padStart(2,'0')).join('');if(hash!==demoPasswordHash)throw new Error('Неверный пароль');onLogin({id:0,name:'Демо-пользователь',email:'',role:'admin',active:true});}else onLogin(await api<User>(setup?'/auth/setup':'/auth/login',{method:'POST',body:JSON.stringify(data)}));}catch(e){setMessage(err(e));}finally{setBusy(false);}}
 return <main className="auth-shell"><div className="auth-panel"><div className="brand"><span className="brand-mark">D</span><strong>DUS <span>Leads</span></strong></div><h1>{demo?'Демо-доступ':setup?'Создайте рабочее пространство':'Вход в рабочее пространство'}</h1><p>{demo?'Введите временный пароль, чтобы открыть интерфейс.':setup?'Первый пользователь получит права администратора.':'Войдите, чтобы продолжить работу с клиентами.'}</p><ErrorBox message={message}/><form onSubmit={submit}>{!demo&&setup&&<Field label="Имя"><input name="name" required autoComplete="name" maxLength={100}/></Field>}{!demo&&<Field label="Электронная почта"><input name="email" type="email" required autoComplete="email"/></Field>}<Field label="Пароль" hint={demo?'Временный доступ для демонстрации.':setup?'Не менее 12 символов.':undefined}><input name="password" type="password" required minLength={demo?1:setup?12:1} autoComplete={demo?'current-password':setup?'new-password':'current-password'}/></Field><Button type="submit" disabled={busy}>{busy?'Проверяем…':demo?'Открыть':'Войти'}</Button></form><small>Автоматический обзвон и рекламные рассылки не выполняются.</small></div></main>;
}

function Dashboard({revision,analytics,demo=false,onOpenSearch,onOpenLeads,onSelect}:{revision:number;analytics:boolean;demo?:boolean;onOpenSearch:()=>void;onOpenLeads:()=>void;onSelect:(lead:Lead)=>void}){
 const [data,setData]=useState<any>(null),[queue,setQueue]=useState<Lead[]>([]),[error,setError]=useState('');
 useEffect(()=>{let live=true;if(demo){setData({total:4,promising:3,new_today:4,interested:1,paid_orders:0,conversion:0,revenue:0,without_website:4,paid_today:0,daily_goal:1,calls:0,by_city:[],by_category:[],by_employee:[]});setQueue([demoLead(1,'Демо: Автоцентр «Север»',86,'not_listed'),demoLead(2,'Демо: Garage 24',74,'mobile'),demoLead(3,'Демо: Моторсервис',62,'rating')]);return()=>{live=false;};}Promise.all([api('/dashboard'),api<{items:Lead[]}>(`/leads?page=1&page_size=6&sort=-score`)]).then(([summary,leads])=>{if(live){setData(summary);setQueue(leads.items||[]);setError('');}}).catch(e=>live&&setError(err(e)));return()=>{live=false;};},[revision,demo]);
 if(error)return <ErrorBox message={error}/>;if(!data)return <Loading/>;
 const metrics=[['В базе',data.total??data.total_leads??0],['Перспективные',data.promising??0],['Новых сегодня',data.new_today??0],['Заинтересованы',data.interested??0],['Оплачено',data.paid_orders??data.paid??0],['Конверсия',`${data.conversion??0}%`],['Выручка',money(data.revenue)],['Без сайта',data.without_website??data.not_listed??0]];
 const groups=[['По городам',(data.by_city||[]).map((x:any)=>({...x,count:x.value}))],['По категориям',(data.by_category||[]).map((x:any)=>({...x,count:x.value}))],['По сотрудникам',(data.by_employee||[]).map((x:any)=>({...x,count:x.leads}))]] as [string,any[]][];
 if(analytics)return <><div className="metric-grid analytics-metrics">{metrics.map(([label,value],i)=><div className={`metric ${i===1?'metric-total':''}`} key={label}><span>{label}</span><strong>{value}</strong></div>)}</div><div className="charts-grid">{groups.map(([title,rows])=><section className="panel chart-panel" key={title}><h2>{title}</h2>{rows.length?<ResponsiveContainer width="100%" height={260}><BarChart data={rows.map(x=>({name:x.name??x.city??x.category??x.employee??'Не назначен',value:x.count??x.total??0}))} margin={{top:25,right:8,left:-20,bottom:12}}><CartesianGrid stroke="var(--border)" vertical={false}/><XAxis dataKey="name" tick={{fill:'var(--muted)',fontSize:12}} tickLine={false}/><YAxis allowDecimals={false} tick={{fill:'var(--muted)',fontSize:12}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'var(--surface)',border:'1px solid var(--border)',borderRadius:4}}/><Bar dataKey="value" name="Организаций" fill="var(--accent)" radius={[2,2,0,0]}/></BarChart></ResponsiveContainer>:<p className="muted padded">Данных для этого разреза пока нет.</p>}</section>)}</div></>;
 if((data.total??data.total_leads??0)===0)return <section className="panel"><Empty title="База клиентов пока пуста" text="Запустите поиск с ключом API или импортируйте CSV и Excel с доступными вам данными." action={<Button onClick={onOpenSearch}><Search size={17}/>Настроить поиск</Button>}/></section>;
 const overdue=queue.filter(lead=>lead.next_contact&&new Date(lead.next_contact)<new Date()).length;
 return <div className="dispatch-layout"><section className="dispatch-board"><div className="dispatch-heading"><div><span className="eyebrow">Очередь на смену</span><h2>Кому звонить сейчас</h2><p>Сначала компании с сильным сигналом и понятной причиной для контакта.</p></div><Button variant="ghost" onClick={onOpenLeads}>Вся очередь<ArrowRight size={17}/></Button></div><ol className="priority-queue">{queue.map((lead,index)=>{const reason=lead.score_reasons?.[0];return <li key={lead.id}><span className="queue-rank" aria-hidden="true">{String(index+1).padStart(2,'0')}</span><div className="queue-main"><button className="queue-name" onClick={()=>onSelect(lead)}>{lead.name}</button><p>{lead.category||'Категория не указана'} · {lead.city||'Город не указан'}</p><span className="why-now">{reason?ruleLabels[reason.rule]||reason.rule:'Нужна ручная оценка'}{reason?.points?` · +${reason.points}`:''}</span></div><div className="queue-due"><Clock3 size={15}/><span>{lead.next_contact?date(lead.next_contact):'Контакт не назначен'}</span></div><Score value={lead.score}/>{lead.phone?<a className="queue-call" href={`tel:${lead.phone.replace(/[^+\d]/g,'')}`} aria-label={`Позвонить в ${lead.name}`}><Phone size={17}/><span>{lead.phone}</span></a>:<button className="queue-open" onClick={()=>onSelect(lead)}>Открыть<ArrowRight size={16}/></button>}</li>})}</ol></section><aside className="shift-rail" aria-label="Сводка смены"><div className="shift-index"><span className="eyebrow">Смена сегодня</span><strong>{data.paid_today??0}<span> / {data.daily_goal??1}</span></strong><p>оплаченных заказов</p><progress aria-label="Выполнение цели продаж" value={Math.min(data.paid_today??0,data.daily_goal??1)} max={data.daily_goal??1}/></div><dl className="shift-stats"><div><dt>Требуют внимания</dt><dd>{data.promising??0}</dd></div><div><dt>Просрочен контакт</dt><dd className={overdue?'warning-text':''}>{overdue}</dd></div><div><dt>Без сайта</dt><dd>{data.without_website??data.not_listed??0}</dd></div><div><dt>Звонков сегодня</dt><dd>{data.calls??0}</dd></div></dl><Button onClick={onOpenLeads}>Разобрать очередь<ArrowRight size={17}/></Button><p className="rail-note">Оценка объясняет приоритет, но не предсказывает покупку.</p></aside></div>;
}

function SearchPage({notify,onCreated}:{notify:(s:string)=>void;onCreated:()=>void}){
 const [cities,setCities]=useState(''),[cats,setCats]=useState<string[]>([]),[custom,setCustom]=useState(''),[sources,setSources]=useState<string[]>([]),[capabilities,setCapabilities]=useState<any>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const [criteria,setCriteria]=useState({min_rating:0,min_reviews:0,max_results:100,without_website:false,broken_website:false,with_phone:false,exclude_existing:true,exclude_chains:false,analyze_websites:false});
 useEffect(()=>{api('/sources').then(setCapabilities).catch(e=>setError(err(e)));},[]);
 const toggleCat=(value:string)=>setCats(prev=>prev.includes(value)?prev.filter(c=>c!==value):[...prev,value]);
 const caps=Array.isArray(capabilities)?capabilities:capabilities?.items||capabilities?.sources||[];
 async function submit(e:FormEvent){e.preventDefault();setError('');if(!list(cities).length||!cats.length||!sources.length){setError('Укажите хотя бы один город, категорию и источник.');return;}setBusy(true);try{await api('/searches',{method:'POST',body:JSON.stringify({...criteria,cities:list(cities),categories:cats,sources})});notify('Поиск добавлен в очередь');onCreated();}catch(e){setError(err(e));}finally{setBusy(false);}}
 return <form className="search-layout" onSubmit={submit}><div className="search-main"><section className="panel"><h2>География и бизнес</h2><Field label="Города России" hint="Несколько городов разделяйте запятой."><input placeholder="Например, Казань, Самара" value={cities} onChange={e=>setCities(e.target.value)} required/></Field><div className="field"><span>Категории бизнеса</span><div className="category-grid">{categories.map(c=><Toggle key={c} label={c} checked={cats.includes(c)} onChange={()=>toggleCat(c)}/>)}</div></div><div className="inline-add"><Field label="Своя категория"><input value={custom} onChange={e=>setCustom(e.target.value)} placeholder="Название категории"/></Field><Button variant="secondary" type="button" disabled={!custom.trim()} onClick={()=>{setCats(prev=>[...new Set([...prev,custom.trim()])]);setCustom('');}}>Добавить</Button></div>{cats.filter(c=>!categories.includes(c)).map(c=><button type="button" className="tag" key={c} onClick={()=>toggleCat(c)}>{c}<X size={13}/></button>)}</section><section className="panel"><h2>Условия отбора</h2><div className="form-grid"><Field label="Минимальный рейтинг"><input type="number" min="0" max="5" step="0.1" value={criteria.min_rating} onChange={e=>setCriteria({...criteria,min_rating:+e.target.value})}/></Field><Field label="Минимум отзывов"><input type="number" min="0" value={criteria.min_reviews} onChange={e=>setCriteria({...criteria,min_reviews:+e.target.value})}/></Field><Field label="Лимит результатов"><input type="number" min="1" max="10000" value={criteria.max_results} onChange={e=>setCriteria({...criteria,max_results:+e.target.value})}/></Field></div><div className="checkbox-list">{([['without_website','Только без указанного сайта'],['broken_website','Только с недоступным сайтом'],['with_phone','Только с телефоном'],['exclude_existing','Исключить ранее найденные организации'],['exclude_chains','Исключить подтверждённые сети'],['analyze_websites','Проверять существующие сайты']] as const).map(([key,label])=><Toggle key={key} label={label} checked={criteria[key]} onChange={v=>setCriteria({...criteria,[key]:v,...(key==='without_website'&&v?{broken_website:false}:{}),...(key==='broken_website'&&v?{without_website:false,analyze_websites:true}:{})})}/>)}</div><p className="form-hint">Отсутствие ссылки в карточке означает «сайт не указан». Это не подтверждает отсутствие сайта у компании.</p></section></div><aside className="search-aside"><section className="panel"><h2>Источники данных</h2>{['yandex','2gis'].map(source=>{const cap=caps.find((x:any)=>[source,source==='2gis'?'dgis':source].includes(x.id??x.source??x.name));return <div className="source-option" key={source}><Toggle label={sourceLabels[source]} checked={sources.includes(source)} onChange={v=>setSources(prev=>v?[...prev,source]:prev.filter(x=>x!==source))}/><small>{cap?.message??cap?.reason??cap?.limitations??'Нужны API-ключ и разрешение на хранение данных в CRM.'}</small></div>;})}<p className="form-hint">Ключи задаются в .env на сервере. Без доступа к API можно импортировать CSV или Excel в разделе «База клиентов».</p></section><section className="panel search-summary"><h2>Параметры поиска</h2><dl><div><dt>Городов</dt><dd>{list(cities).length}</dd></div><div><dt>Категорий</dt><dd>{cats.length}</dd></div><div><dt>Источников</dt><dd>{sources.length}</dd></div><div><dt>Максимум результатов</dt><dd>{criteria.max_results}</dd></div></dl><ErrorBox message={error}/><Button type="submit" disabled={busy}><Search size={17}/>{busy?'Добавление…':'Запустить поиск'}</Button></section></aside></form>;
}

function LeadsPage({promising,users,revision,refresh,notify,onSelect}:{promising:boolean;users:User[];revision:number;refresh:()=>void;notify:(s:string)=>void;onSelect:(lead:Lead)=>void}){
 const [filters,setFilters]=useState({q:'',status:'',city:'',category:'',min_score:promising?'60':'',website_state:'',owner_id:'',sort:'-score'}),[page,setPage]=useState(1),[result,setResult]=useState<{items:Lead[];total:number}|null>(null),[selected,setSelected]=useState<number[]>([]),[error,setError]=useState(''),[busy,setBusy]=useState(false),[more,setMore]=useState(false),[format,setFormat]=useState('xlsx'),[assign,setAssign]=useState(''),[saved,setSaved]=useState<any[]>([]),[filterName,setFilterName]=useState(''),[add,setAdd]=useState(false);
 const params=()=>{const query=new URLSearchParams({page:String(page),page_size:'25'});Object.entries(filters).forEach(([key,value])=>{if(value)query.set(key,value);});return query;};
 useEffect(()=>{let live=true;setError('');const timer=setTimeout(()=>api<{items:Lead[];total:number}>(`/leads?${params()}`).then(data=>{if(live){setResult(data);setSelected([]);}}).catch(e=>live&&setError(err(e))),200);return()=>{live=false;clearTimeout(timer);};},[filters,page,revision]);
 const filter=(key:string,value:string)=>{setPage(1);setFilters(prev=>({...prev,[key]:value}));};
 useEffect(()=>{api<any[]>('/filters').then(setSaved).catch(e=>setError(err(e)));},[]);
 async function bulk(action:string){if(!selected.length)return;if(action==='delete'&&!window.confirm(`Удалить выбранные организации (${selected.length})? Восстановление недоступно.`))return;setBusy(true);try{await api('/leads/bulk',{method:'POST',body:JSON.stringify({ids:selected,action,owner_id:assign?+assign:null,versions:Object.fromEntries((result?.items||[]).filter(l=>selected.includes(l.id)).map(l=>[String(l.id),l.version]))})});notify(action==='delete'?'Организации удалены':'Ответственный назначен');refresh();}catch(e){setError(err(e));}finally{setBusy(false);}}
 async function exportRows(){try{const query=params();query.set('format',format);if(selected.length)query.set('ids',selected.join(','));await download(`/export?${query}`,`dus-leads.${format}`);}catch(e){setError(err(e));}}
 async function importRows(file:File){setBusy(true);const body=new FormData();body.append('file',file);try{const data=await api('/import',{method:'POST',body});notify(`Импорт завершён: ${data.imported??data.created??0} новых записей, ${data.duplicates??0} дубликатов`);refresh();}catch(e){setError(err(e));}finally{setBusy(false);}}
 const saveFilter=async()=>{if(!filterName.trim())return;const value=[...saved.filter(f=>f.name!==filterName.trim()),{name:filterName.trim(),filters}];try{await api('/filters',{method:'PUT',body:JSON.stringify(value)});setSaved(value);setFilterName('');notify('Фильтр сохранён');}catch(e){setError(err(e));}};
 return <><div className="panel table-panel"><div className="table-toolbar"><div className="search-input"><Search size={17}/><input aria-label="Поиск организации" placeholder="Название, телефон, адрес" value={filters.q} onChange={e=>filter('q',e.target.value)}/></div><Button variant="secondary" onClick={()=>setMore(!more)} aria-expanded={more}><SlidersHorizontal size={16}/>Фильтры</Button><span className="toolbar-spacer"/><Button variant="secondary" onClick={()=>setAdd(!add)}><Plus size={16}/>Добавить</Button><label className={`button secondary ${busy?'disabled':''}`}><Upload size={16}/>Импорт<input type="file" className="visually-hidden" accept=".csv,.xlsx" disabled={busy} onChange={e=>{if(e.target.files?.[0])void importRows(e.target.files[0]);e.target.value='';}}/></label><select aria-label="Формат экспорта" value={format} onChange={e=>setFormat(e.target.value)}><option value="xlsx">Excel (.xlsx)</option><option value="csv">Таблица (.csv)</option><option value="json">Данные (.json)</option></select><Button variant="secondary" onClick={exportRows}><Download size={16}/>Экспорт{selected.length?` (${selected.length})`:''}</Button></div>
 {more&&<div className="filter-panel"><div className="form-grid"><Field label="Город"><input value={filters.city} onChange={e=>filter('city',e.target.value)}/></Field><Field label="Категория"><input value={filters.category} onChange={e=>filter('category',e.target.value)}/></Field><Field label="Статус"><select value={filters.status} onChange={e=>filter('status',e.target.value)}><option value="">Все статусы</option>{statuses.map(s=><option key={s}>{s}</option>)}</select></Field><Field label="Минимальная оценка"><input type="number" min="0" max="100" value={filters.min_score} onChange={e=>filter('min_score',e.target.value)}/></Field><Field label="Состояние сайта"><select value={filters.website_state} onChange={e=>filter('website_state',e.target.value)}><option value="">Любое</option>{Object.entries(websiteLabels).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></Field><Field label="Ответственный"><select value={filters.owner_id} onChange={e=>filter('owner_id',e.target.value)}><option value="">Все сотрудники</option>{users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></Field></div><div className="filter-save"><input placeholder="Название фильтра" aria-label="Название сохраняемого фильтра" value={filterName} onChange={e=>setFilterName(e.target.value)}/><Button variant="secondary" onClick={saveFilter} disabled={!filterName.trim()}>Сохранить</Button>{saved.length>0&&<select aria-label="Сохранённые фильтры" defaultValue="" onChange={e=>{const item=saved.find(s=>s.name===e.target.value);if(item){setFilters(item.filters);setPage(1);}e.target.value='';}}><option value="">Сохранённые фильтры</option>{saved.map(s=><option key={s.name}>{s.name}</option>)}</select>}</div></div>}
 {add&&<AddLead onCancel={()=>setAdd(false)} onAdded={()=>{setAdd(false);refresh();notify('Организация добавлена');}}/>}
 <ErrorBox message={error}/>{selected.length>0&&<div className="bulk-bar"><strong>Выбрано: {selected.length}</strong><select aria-label="Назначить ответственного" value={assign} onChange={e=>setAssign(e.target.value)}><option value="">Без ответственного</option>{users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select><Button variant="secondary" size="sm" disabled={busy} onClick={()=>bulk('assign')}>Назначить</Button><Button variant="destructive" size="sm" disabled={busy} onClick={()=>bulk('delete')}>Удалить</Button></div>}
 {!result?<Loading/>:result.items.length===0?<Empty title="Организаций не найдено" text={result.total===0?'Запустите поиск, импортируйте файл или измените условия отбора.':'Измените условия фильтра.'}/>:<div className="table-scroll"><table><thead><tr><th><input aria-label="Выбрать все записи страницы" type="checkbox" checked={result.items.length>0&&result.items.every(l=>selected.includes(l.id))} onChange={e=>setSelected(e.target.checked?result.items.map(l=>l.id):[])}/></th><th>Организация</th><th>Контакты</th><th>Сайт</th><th><button className="sort-button" onClick={()=>filter('sort',filters.sort==='-score'?'score':'-score')}>Оценка<ArrowUpDown size={13}/></button></th><th>Статус / сотрудник</th></tr></thead><tbody>{result.items.map(lead=><tr key={lead.id}><td className="select-cell"><input type="checkbox" aria-label={`Выбрать ${lead.name}`} checked={selected.includes(lead.id)} onChange={e=>setSelected(prev=>e.target.checked?[...prev,lead.id]:prev.filter(id=>id!==lead.id))}/></td><td data-label="Организация"><button className="lead-name" onClick={()=>onSelect(lead)}>{lead.name}</button><small>{lead.category||'Категория не указана'}</small><small>{lead.city}{lead.address?`, ${lead.address}`:''}</small><span className="source-name">{sourceLabels[lead.source]||lead.source}</span></td><td data-label="Контакты">{lead.phone?<a href={`tel:${lead.phone.replace(/[^+\d]/g,'')}`} className="phone-link">{lead.phone}</a>:<span className="muted">Телефон не указан</span>}<small>{lead.email||'Почта не указана'}</small><small>{lead.rating!=null?`Рейтинг ${lead.rating}, ${lead.review_count??0} отзывов`:'Рейтинг не указан'}</small></td><td data-label="Сайт"><span className={`website-state ${lead.website_status==='unavailable'?'warning-text':''}`}>{websiteLabels[lead.website_status]||'Не проверен'}</span>{safeUrl(lead.website)&&<a className="site-link" href={safeUrl(lead.website)} target="_blank" rel="noopener noreferrer">{new URL(safeUrl(lead.website)!).hostname}<ExternalLink size={11}/></a>}</td><td data-label="Приоритет"><Score value={lead.score}/><small className="score-reason">{lead.score_reasons?.[0]?(ruleLabels[lead.score_reasons[0].rule]||lead.score_reasons[0].rule):'Нет факторов оценки'}</small></td><td data-label="Работа"><span className="crm-status">{lead.status}</span><small>{users.find(u=>u.id===lead.owner_id)?.name||'Не назначен'}</small>{lead.next_contact&&<small><Clock3 size={12}/>{date(lead.next_contact)}</small>}</td></tr>)}</tbody></table></div>}
 <div className="pagination"><span>{result?`${result.total.toLocaleString('ru-RU')} организаций`:'Загрузка…'}</span><div><span>Страница {page} из {Math.max(1,Math.ceil((result?.total||0)/25))}</span><Button variant="ghost" size="icon" aria-label="Предыдущая страница" disabled={page===1} onClick={()=>setPage(page-1)}><ChevronLeft size={17}/></Button><Button variant="ghost" size="icon" aria-label="Следующая страница" disabled={!result||page*25>=result.total} onClick={()=>setPage(page+1)}><ChevronRight size={17}/></Button></div></div></div><p className="form-hint">Экспорт зависит от разрешений источника. Импорт: CSV в UTF-8 или Excel XLSX с заголовками name, city, category, address, phone, website.</p></>;
}

function AddLead({onCancel,onAdded}:{onCancel:()=>void;onAdded:()=>void}){
 const [error,setError]=useState(''),[busy,setBusy]=useState(false);
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');const body=Object.fromEntries(new FormData(e.currentTarget));try{await api('/leads',{method:'POST',body:JSON.stringify(body)});onAdded();}catch(e){setError(err(e));}finally{setBusy(false);}}
 return <form className="inline-form" onSubmit={submit}><h2>Добавить организацию вручную</h2><div className="form-grid">{[['name','Название',true],['city','Город',true],['category','Категория',false],['address','Адрес',false],['phone','Телефон',false],['website','Сайт',false]].map(([name,label,required])=><Field key={String(name)} label={String(label)}><input name={String(name)} required={Boolean(required)} type={name==='website'?'url':'text'}/></Field>)}</div><ErrorBox message={error}/><div className="button-row"><Button disabled={busy} type="submit">{busy?'Сохранение…':'Добавить организацию'}</Button><Button variant="ghost" type="button" onClick={onCancel}>Отмена</Button></div></form>;
}

function LeadDetail({lead,users,onClose,onSaved,notify}:{lead:Lead;users:User[];onClose:()=>void;onSaved:()=>void;notify:(s:string)=>void}){
 const [current,setCurrent]=useState(lead),[data,setData]=useState({status:lead.status,owner_id:lead.owner_id?.toString()||'',notes:lead.notes||'',order_value:lead.order_value??15000,next_contact:localInputDate(lead.next_contact),consent:lead.consent||'unknown'}),[events,setEvents]=useState<any[]>([]),[comment,setComment]=useState(''),[kind,setKind]=useState('note'),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const loadEvents=()=>api(`/leads/${lead.id}/interactions`).then(rows=>setEvents(Array.isArray(rows)?rows:rows.items||[])).catch(e=>setError(err(e)));
 useEffect(()=>{loadEvents();const previousFocus=document.activeElement as HTMLElement|null;const key=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const controls=Array.from(document.querySelectorAll<HTMLElement>('.drawer button:not(:disabled),.drawer a[href],.drawer input:not(:disabled),.drawer select:not(:disabled),.drawer textarea:not(:disabled)'));const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};window.addEventListener('keydown',key);const prev=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{window.removeEventListener('keydown',key);document.body.style.overflow=prev;previousFocus?.focus();};},[lead.id]);
 async function save(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const saved=await api<Lead>(`/leads/${lead.id}`,{method:'PATCH',body:JSON.stringify({...data,owner_id:data.owner_id?+data.owner_id:null,next_contact:data.next_contact?new Date(data.next_contact).toISOString():null,version:current.version})});setCurrent(saved);onSaved();notify('Карточка сохранена');}catch(e){setError(err(e));}finally{setBusy(false);}}
 async function addEvent(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{await api(`/leads/${lead.id}/interactions`,{method:'POST',body:JSON.stringify({kind,comment})});setComment('');loadEvents();onSaved();}catch(e){setError(err(e));}finally{setBusy(false);}}
 const blocked=data.consent==='denied'||data.status==='Не связываться повторно';
 async function audit(){setBusy(true);setError('');try{const updated=await api<Lead>(`/leads/${lead.id}/audit`,{method:'POST'});setCurrent(updated);onSaved();notify('Проверка сайта завершена');}catch(e){setError(err(e));}finally{setBusy(false);}}
 return <div className="drawer-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className="drawer" role="dialog" aria-modal="true" aria-label={`Карточка ${lead.name}`}><header className="drawer-header"><div><h2>{lead.name}</h2><p>{lead.category}, {lead.city}</p></div><Button variant="ghost" size="icon" aria-label="Закрыть карточку" onClick={onClose} autoFocus><X size={20}/></Button></header><div className="drawer-body"><div className="lead-summary"><Score value={current.score}/><div><strong>Оценка перспективности</strong><p>{(current.score_reasons||[]).map(r=>`${ruleLabels[r.rule]||r.rule}: ${r.points>0?'+':''}${r.points}`).join('; ')||'Нет факторов для начисления баллов.'}</p></div></div><dl className="detail-list">{[['Адрес',lead.address],['Телефон',lead.phone],['Почта',lead.email],['Рейтинг',lead.rating!=null?`${lead.rating} (${lead.review_count??0} отзывов)`:null],['Источник',sourceLabels[lead.source]||lead.source],['Получено',date(lead.collected_at)]].map(([key,value])=><div key={key}><dt>{key}</dt><dd>{value||'Не указано'}</dd></div>)}</dl><div className="button-row">{safeUrl(lead.card_url)&&<a className="button secondary small" href={safeUrl(lead.card_url)} target="_blank" rel="noopener noreferrer">Карточка источника<ExternalLink size={13}/></a>}{safeUrl(lead.website)&&<a className="button secondary small" href={safeUrl(lead.website)} target="_blank" rel="noopener noreferrer">Открыть сайт<ExternalLink size={13}/></a>}</div><h3>Проверка сайта</h3><p>{websiteLabels[current.website_status]||'Не проверен'}</p><Button variant="secondary" size="sm" disabled={busy||!lead.website} onClick={audit}><RefreshCw size={14}/>{busy?'Проверка…':'Проверить сайт'}</Button>{Object.keys(current.audit||{}).length>0&&<dl className="detail-list">{Object.entries(current.audit).filter(([,v])=>typeof v!=='object').map(([key,value])=><div key={key}><dt>{({http_status:'HTTP-статус',https:'HTTPS',load_time_ms:'Загрузка, мс',mobile_friendly:'Мобильная версия',has_contact:'Контакты',has_form:'Форма',has_title:'Заголовок SEO',has_description:'Описание SEO',error:'Ошибка',checked_at:'Дата проверки',response_ms:'Ответ сервера, мс',load_ms:'Получение HTML, мс',has_contacts:'Контакты',has_seo:'Основные SEO-теги',seo_title:'SEO-заголовок',seo_description:'SEO-описание',website_status:'Результат',final_url:'Конечный адрес',method:'Метод проверки'} as Record<string,string>)[key]||key}</dt><dd>{typeof value==='boolean'?(value?'Да':'Нет'):key==='website_status'?(websiteLabels[String(value)]||'Не определено'):String(value??'Не определено')}</dd></div>)}</dl>}{current.audit?.errors?.length>0&&<ul className="audit-errors">{current.audit.errors.map((message:string,i:number)=><li key={i}>{message}</li>)}</ul>}<p className="form-hint">Анализ HTML даёт базовые признаки. Время ответа сервера не является полной скоростью загрузки страницы.</p><ErrorBox message={error}/><form onSubmit={save}><h3>Работа с клиентом</h3><div className="form-grid"><Field label="Статус"><select value={data.status} onChange={e=>setData({...data,status:e.target.value})}>{statuses.map(s=><option key={s}>{s}</option>)}</select></Field><Field label="Ответственный"><select value={data.owner_id} onChange={e=>setData({...data,owner_id:e.target.value})}><option value="">Не назначен</option>{users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></Field><Field label="Стоимость заказа, ₽"><input type="number" min="0" step="1" value={data.order_value} onChange={e=>setData({...data,order_value:+e.target.value})}/></Field><Field label="Следующий контакт"><input type="datetime-local" value={data.next_contact} disabled={blocked} onChange={e=>setData({...data,next_contact:e.target.value})}/></Field></div><Field label="Согласие на рекламную коммуникацию"><select value={data.consent} onChange={e=>setData({...data,consent:e.target.value})}><option value="unknown">Не установлено</option><option value="granted">Получено</option><option value="denied">Отказ от коммуникации</option></select></Field>{blocked&&<p className="warning-text">Повторный контакт запрещён. Запланированные напоминания будут сняты.</p>}<Field label="Заметки"><textarea rows={3} value={data.notes} onChange={e=>setData({...data,notes:e.target.value})}/></Field><Button type="submit" disabled={busy}>{busy?'Сохранение…':'Сохранить карточку'}</Button></form><h3>История взаимодействий</h3><form onSubmit={addEvent}><div className="inline-add"><select aria-label="Тип взаимодействия" value={kind} onChange={e=>setKind(e.target.value)}><option value="note">Комментарий</option><option value="call" disabled={blocked||data.consent!=='granted'}>Звонок</option></select><input aria-label="Комментарий" placeholder="Что обсудили, что сделать дальше" required maxLength={10000} value={comment} onChange={e=>setComment(e.target.value)}/><Button type="submit" disabled={busy||!comment.trim()}>Добавить</Button></div></form><ol className="timeline">{events.map(event=><li key={event.id}><div><strong>{event.kind==='call'?'Звонок':event.kind==='status'?'Изменение статуса':'Комментарий'}</strong><time>{date(event.created_at)}</time></div><p>{event.comment}</p><small>{users.find(u=>u.id===event.user_id)?.name||'Сотрудник'}</small></li>)}</ol>{!events.length&&<p className="muted">Взаимодействий пока нет.</p>}</div></section></div>;
}

function CrmPage({revision,onSelect}:{revision:number;onSelect:(l:Lead)=>void}){
 const [result,setResult]=useState<{items:Lead[];total:number}|null>(null),[error,setError]=useState(''),[status,setStatus]=useState('');
 useEffect(()=>{api(`/leads?page_size=100&sort=-score&${status?`status=${encodeURIComponent(status)}`:''}`).then(setResult).catch(e=>setError(err(e)));},[revision,status]);
 return <><div className="crm-toolbar"><Field label="Этап работы"><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Все этапы</option>{statuses.map(s=><option key={s}>{s}</option>)}</select></Field><p className="muted">{result?.total??0} организаций, показаны первые 100. Все записи доступны в базе клиентов.</p></div><ErrorBox message={error}/>{!result?<Loading/>:!result.items.length?<Empty title="Клиентов на этом этапе нет" text="Добавьте организации в базу и меняйте статус в карточке клиента."/>:<div className="kanban">{statuses.filter(s=>result.items.some(l=>l.status===s)).map(s=><section className="kanban-column" key={s}><h2>{s}<span>{result.items.filter(l=>l.status===s).length}</span></h2>{result.items.filter(l=>l.status===s).map(l=><button className="crm-card" key={l.id} onClick={()=>onSelect(l)}><div><strong>{l.name}</strong><Score value={l.score}/></div><span>{l.category}, {l.city}</span><p>{l.notes||'Заметок пока нет'}</p><footer><span>{money(l.order_value)}</span><span>{l.next_contact?date(l.next_contact):'Контакт не назначен'}</span></footer></button>)}</section>)}</div>}</>;
}

function TeamPage({user,users,refresh,notify}:{user:User;users:User[];refresh:()=>void;notify:(s:string)=>void}){
 const [adding,setAdding]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);try{await api('/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});setAdding(false);refresh();notify('Сотрудник добавлен');}catch(e){setError(err(e));}finally{setBusy(false);}}
 return <><div className="section-heading"><h2>Команда <span className="muted">{users.length}</span></h2>{user.role==='admin'&&<Button onClick={()=>setAdding(!adding)}><Plus size={16}/>Добавить сотрудника</Button>}</div><ErrorBox message={error}/>{adding&&<form className="panel" onSubmit={submit}><div className="form-grid"><Field label="Имя"><input required name="name"/></Field><Field label="Почта"><input required name="email" type="email"/></Field><Field label="Временный пароль"><input required name="password" type="password" minLength={12}/></Field><Field label="Роль"><select name="role"><option value="staff">Сотрудник</option><option value="admin">Администратор</option></select></Field></div><Button type="submit" disabled={busy}>Создать пользователя</Button></form>}<div className="panel table-panel table-scroll"><table><thead><tr><th>Сотрудник</th><th>Электронная почта</th><th>Роль</th><th>Доступ</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><span className="name-cell"><span className="avatar">{u.name.slice(0,1)}</span>{u.name}{u.id===user.id&&<small>Вы</small>}</span></td><td>{u.email}</td><td>{u.role==='admin'?'Администратор':'Сотрудник'}</td><td>{u.active?'Активен':'Отключён'}</td></tr>)}</tbody></table></div><p className="form-hint">Назначение клиентов выполняется в базе клиентов. Изменения карточки защищены от одновременного сохранения разными сотрудниками.</p></>;
}

function HistoryPage({onSelect,notify}:{onSelect:(l:Lead)=>void;notify:(s:string)=>void}){
 const [jobs,setJobs]=useState<SearchJob[]|null>(null),[error,setError]=useState(''),[open,setOpen]=useState<number|null>(null),[results,setResults]=useState<Lead[]>([]),[format,setFormat]=useState('xlsx');
 const load=()=>api('/searches').then(rows=>setJobs(Array.isArray(rows)?rows:rows.items||[])).catch(e=>setError(err(e)));
 useEffect(()=>{load();const timer=setInterval(load,2500);return()=>clearInterval(timer);},[]);
 async function show(id:number){if(open===id){setOpen(null);return;}setOpen(id);setResults([]);try{const data=await api(`/leads?search_id=${id}&page_size=100`);setResults(data.items);}catch(e){setError(err(e));}}
 async function stop(id:number){try{await api(`/searches/${id}/cancel`,{method:'POST'});notify('Запрошена остановка поиска');load();}catch(e){setError(err(e));}}
 return <><ErrorBox message={error}/>{!jobs?<Loading/>:!jobs.length?<Empty title="Поисков пока не было" text="Создайте поиск по нужным городам и категориям. Здесь появятся прогресс и результаты."/>:<div className="history-list">{jobs.map(job=><section className="panel" key={job.id}><div className="section-heading"><div><h2>{job.criteria.cities?.join(', ')||'Поиск организаций'}</h2><p>{job.criteria.categories?.join(', ')}</p></div><span className={`status-label ${job.status==='failed'?'warning-text':''}`}>{jobsLabels[job.status]||job.status}</span></div><div className="job-meta"><span>{date(job.created_at)}</span><span>Найдено: <strong>{job.found}</strong></span><span>Источники: {job.criteria.sources?.map((s:string)=>sourceLabels[s]||s).join(', ')}</span></div><progress value={job.progress} max={100} aria-label="Прогресс поиска"/><div className="button-row"><Button variant="secondary" size="sm" onClick={()=>show(job.id)}>{open===job.id?'Скрыть результаты':'Результаты'}</Button>{['queued','running'].includes(job.status)&&<Button variant="destructive" size="sm" onClick={()=>stop(job.id)}>Остановить</Button>}<select aria-label={`Формат экспорта поиска ${job.id}`} value={format} onChange={e=>setFormat(e.target.value)}><option value="xlsx">Excel (.xlsx)</option><option value="csv">Таблица (.csv)</option><option value="json">Данные (.json)</option></select><Button variant="ghost" size="sm" onClick={async()=>{try{await download(`/export?format=${format}&search_id=${job.id}`,`search-${job.id}.${format}`);}catch(e){setError(err(e));}}}><Download size={14}/>Экспорт поиска</Button></div>{job.errors?.length>0&&<details><summary>Сообщения задачи ({job.errors.length})</summary><ul className="job-errors">{job.errors.map((message,i)=><li key={i}>{typeof message==='string'?message:JSON.stringify(message)}</li>)}</ul></details>}{open===job.id&&<div className="job-results">{results.length?results.map(l=><button key={l.id} onClick={()=>onSelect(l)}><span>{l.name}<small>{l.city}, {l.category}</small></span><Score value={l.score}/></button>):<p className="muted">Сохранённых результатов пока нет.</p>}</div>}</section>)}</div>}</>;
}

function SettingsPage({user,notify}:{user:User;notify:(s:string)=>void}){
 const [data,setData]=useState<any>(null),[sources,setSources]=useState<any>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[priority,setPriority]=useState('');
 useEffect(()=>{api('/settings').then(d=>{setData(d);setPriority((d.priority_categories||[]).join(', '));}).catch(e=>setError(err(e)));api('/sources').then(setSources).catch(e=>setError(err(e)));},[]);
 async function save(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const result=await api('/settings',{method:'PUT',body:JSON.stringify({...data,priority_categories:list(priority)})});setData(result);notify('Настройки сохранены, оценки пересчитаны');}catch(e){setError(err(e));}finally{setBusy(false);}}
 const caps=Array.isArray(sources)?sources:sources?.items||sources?.sources||[];
 return <><ErrorBox message={error}/>{!data?<Loading/>:<form className="settings-layout" onSubmit={save}><section className="panel"><h2>Оценка перспективности</h2><p className="muted">Сумма факторов ограничена диапазоном от 0 до 100. Закрытые организации исключаются.</p><div className="weight-list">{Object.entries(data.weights||{}).map(([key,value])=><Field key={key} label={ruleLabels[key]||key}><input disabled={user.role!=='admin'} type="number" min="-100" max="100" value={value as number} onChange={e=>setData({...data,weights:{...data.weights,[key]:+e.target.value}})}/></Field>)}</div><Field label="Приоритетные категории" hint="Перечислите через запятую."><textarea disabled={user.role!=='admin'} rows={3} value={priority} onChange={e=>setPriority(e.target.value)}/></Field></section><div><section className="panel"><h2>Цель и ограничения</h2><Field label="Оплаченных заказов в день"><input disabled={user.role!=='admin'} type="number" min="1" max="1000" value={data.daily_goal} onChange={e=>setData({...data,daily_goal:+e.target.value})}/></Field><Field label="Стоимость заказа по умолчанию, ₽"><input disabled={user.role!=='admin'} type="number" min="0" value={data.default_order_value} onChange={e=>setData({...data,default_order_value:+e.target.value})}/></Field><Field label="Максимум API-запросов на поиск" hint="Ограничивает расход. Стоимость запроса определяется договором с поставщиком."><input disabled={user.role!=='admin'} type="number" min="1" max="10000" value={data.api_request_budget} onChange={e=>setData({...data,api_request_budget:+e.target.value})}/></Field><Field label="Оценочная цена API-запроса, ₽" hint="Укажите цену из вашего договора."><input disabled={user.role!=='admin'} type="number" min="0" step="0.01" value={data.api_request_cost_rub} onChange={e=>setData({...data,api_request_cost_rub:+e.target.value})}/></Field><Field label="Лимит расходов на поиск, ₽"><input disabled={user.role!=='admin'} type="number" min="0" step="0.01" value={data.api_spend_limit_rub} onChange={e=>setData({...data,api_spend_limit_rub:+e.target.value})}/></Field>{user.role==='admin'?<Button type="submit" disabled={busy}>{busy?'Сохранение…':'Сохранить настройки'}</Button>:<p className="form-hint">Изменять настройки может администратор.</p>}</section><section className="panel"><h2>Подключение источников</h2>{caps.length?caps.map((source:any,i:number)=><div key={source.id||source.source||i} className="source-info"><strong>{sourceLabels[source.id??source.source]||source.name||source.source}</strong>{Object.entries(source).filter(([key])=>!['id','name','source'].includes(key)).map(([key,value])=><p key={key}><span>{({configured:'Ключ настроен',enabled:'Доступен',available:'Доступен',persistence_allowed:'Хранение разрешено',storage_allowed:'Хранение разрешено',export_allowed:'Экспорт разрешён',message:'Ограничение',reason:'Причина',limitations:'Ограничения'} as Record<string,string>)[key]||key}: </span>{typeof value==='boolean'?(value?'Да':'Нет'):Array.isArray(value)?value.join('; '):String(value??'Не указано')}</p>)}</div>):<p className="muted">Информация об источниках недоступна.</p>}<p className="form-hint">API-ключи и разрешения на хранение задаются на сервере в .env. Не передавайте ключи в браузер.</p></section></div></form>}</>;
}
